{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.fees import card_fee"
  ],
  "tests": [
    {
      "name": "test_card_fee_minimum_applies_for_small_amount",
      "intent": "minimum fee is charged when percentage fee is below minimum",
      "code": "# intent: minimum fee is charged when percentage fee is below minimum\ndef test_card_fee_minimum_applies_for_small_amount():\n    assert card_fee(Decimal(\"5.00\")) == Decimal(\"0.30\")\n"
    },
    {
      "name": "test_card_fee_percentage_applies_when_above_minimum",
      "intent": "percentage fee is charged when it exceeds the minimum",
      "code": "# intent: percentage fee is charged when it exceeds the minimum\ndef test_card_fee_percentage_applies_when_above_minimum():\n    assert card_fee(Decimal(\"100.00\")) == Decimal(\"2.90\")\n"
    },
    {
      "name": "test_card_fee_exactly_at_minimum",
      "intent": "fee equals minimum when percentage fee equals minimum",
      "code": "# intent: fee equals minimum when percentage fee equals minimum\ndef test_card_fee_exactly_at_minimum():\n    # amount where 2.9% = 0.30: 0.30 / 0.029 ≈ 10.3448275862\n    # rounded to cents: 10.34 gives 0.29986 -> rounds to 0.30\n    assert card_fee(Decimal(\"10.34\")) == Decimal(\"0.30\")\n"
    },
    {
      "name": "test_card_fee_rounding_half_up",
      "intent": "percentage fee is rounded to nearest cent using half-up",
      "code": "# intent: percentage fee is rounded to nearest cent using half-up\ndef test_card_fee_rounding_half_up():\n    # 2.9% of 1.72 = 0.04988 -> rounds to 0.05\n    assert card_fee(Decimal(\"1.72\")) == Decimal(\"0.05\")\n"
    },
    {
      "name": "test_card_fee_zero_amount_charges_minimum",
      "intent": "zero amount still incurs minimum fee",
      "code": "# intent: zero amount still incurs minimum fee\ndef test_card_fee_zero_amount_charges_minimum():\n    assert card_fee(Decimal(\"0.00\")) == Decimal(\"0.30\")\n"
    },
    {
      "name": "test_card_fee_negative_amount_raises",
      "intent": "negative amount raises ValueError",
      "code": "# intent: negative amount raises ValueError\ndef test_card_fee_negative_amount_raises():\n    with pytest.raises(ValueError):\n        card_fee(Decimal(\"-1.00\"))\n"
    }
  ]
}
